import{_ as t,o as n,c as r,a as o}from"./app.DLPSkIGI.js";const g=JSON.parse('{"title":"Track 1 Architecture Decisions & Rationale","description":"","frontmatter":{},"headers":[],"relativePath":"changes/hexagonal-split-track-1/TRACK1_ARCHITECTURE_DECISIONS.md","filePath":"changes/hexagonal-split-track-1/TRACK1_ARCHITECTURE_DECISIONS.md","lastUpdated":1771816099000}'),i={name:"changes/hexagonal-split-track-1/TRACK1_ARCHITECTURE_DECISIONS.md"};function a(s,e,l,d,c,u){return n(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="track-1-architecture-decisions-rationale" tabindex="-1">Track 1 Architecture Decisions &amp; Rationale <a class="header-anchor" href="#track-1-architecture-decisions-rationale" aria-label="Permalink to &quot;Track 1 Architecture Decisions &amp; Rationale&quot;">​</a></h1><h2 id="adr-001-port-pareto-algorithm-from-python-to-go" tabindex="-1">ADR-001: Port Pareto Algorithm from Python to Go <a class="header-anchor" href="#adr-001-port-pareto-algorithm-from-python-to-go" aria-label="Permalink to &quot;ADR-001: Port Pareto Algorithm from Python to Go&quot;">​</a></h2><p>undefined<strong>Decision:</strong> Rewrite the Pareto frontier routing algorithm from Python (thegent) in Go (CLIProxy), rather than exposing thegent&#39;s router via FFI.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Pure Go implementation:</strong> Allows CLIProxy to run standalone without Python dependency</li><li>undefined<strong>Performance:</strong> Native Go is 5–10x faster than Python-via-FFI for constraint filtering + frontier computation</li><li>undefined<strong>Maintenance:</strong> Single algorithm in one language, easier to reason about and optimize</li><li>undefined<strong>Terminal Bench 2.0 integration:</strong> Model metrics are already in Go (CLIProxy registry), no translation needed</li></ul><p>undefined<strong>Alternative Rejected:</strong> Expose thegent&#39;s Pareto router via cgo/FFI</p><ul><li>Adds complexity (FFI boundary)</li><li>Slower (marshaling overhead)</li><li>Ties CLIProxy to Python runtime</li></ul><p>undefined<strong>Trade-off:</strong> ~600 LOC rewrite vs. ~200 LOC FFI binding. Rewrite wins on simplicity and performance.</p><p>undefined<strong>Validation:</strong> T1.5 parity test confirms identical model selection.</p><hr><h2 id="adr-002-expose-routing-as-http-endpoint-not-direct-lib-call" tabindex="-1">ADR-002: Expose Routing as HTTP Endpoint, Not Direct Lib Call <a class="header-anchor" href="#adr-002-expose-routing-as-http-endpoint-not-direct-lib-call" aria-label="Permalink to &quot;ADR-002: Expose Routing as HTTP Endpoint, Not Direct Lib Call&quot;">​</a></h2><p>undefined<strong>Decision:</strong> CLIProxy exposes routing via <code>POST /v1/routing/select</code> HTTP endpoint, not as a Go library that thegent imports.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Decoupling:</strong> thegent and CLIProxy are independent processes; no shared code</li><li>undefined<strong>Boundary clarity:</strong> Clear separation of concerns (orchestration vs. routing)</li><li>undefined<strong>Scalability:</strong> CLIProxy can scale independently; multiple thegent instances share routing service</li><li>undefined<strong>Future multitenancy:</strong> HTTP endpoint can be exposed to other clients (IDE, other agents)</li><li>undefined<strong>Testing:</strong> HTTP mocking is simpler than mocking Go libraries</li></ul><p>undefined<strong>Alternative Rejected:</strong> Go library that thegent calls via cgo</p><ul><li>Adds FFI complexity</li><li>Couples thegent to CLIProxy&#39;s Go runtime</li><li>Harder to scale (processes tied together)</li></ul><p>undefined<strong>Trade-off:</strong> Network latency (~10ms per routing decision) is acceptable for task-level routing (1 decision per 1–5 minutes of execution).</p><p>undefined<strong>Validation:</strong> T5.4 E2E test measures end-to-end latency.</p><hr><h2 id="adr-003-consolidate-auth-into-cliproxy-oauth-token-manager" tabindex="-1">ADR-003: Consolidate Auth into CLIProxy OAuth Token Manager <a class="header-anchor" href="#adr-003-consolidate-auth-into-cliproxy-oauth-token-manager" aria-label="Permalink to &quot;ADR-003: Consolidate Auth into CLIProxy OAuth Token Manager&quot;">​</a></h2><p>undefined<strong>Decision:</strong> Merge thegent&#39;s OAuth lifecycle management into CLIProxy&#39;s centralized token manager, with HTTP endpoints for refresh/revoke.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Single source of truth:</strong> One OAuth state for all agents/providers</li><li>undefined<strong>Token refresh in one place:</strong> CLIProxy manages expiration/refresh logic</li><li>undefined<strong>Credential security:</strong> Tokens stored in CLIProxy process, not scattered across agent instances</li><li>undefined<strong>HTTP for token ops:</strong> thegent calls <code>POST /v1/auth/oauth/refresh</code> instead of managing tokens locally</li></ul><p>undefined<strong>Alternative Rejected:</strong> Keep OAuth in thegent, have CLIProxy call back to thegent</p><ul><li>Circular dependency (thegent ↔ CLIProxy)</li><li>Difficult to reason about token state</li><li>Harder to add new agents (each must re-implement OAuth)</li></ul><p>undefined<strong>Trade-off:</strong> All agents depend on CLIProxy for token refresh; if CLIProxy is down, no auth. Mitigation: cache tokens in-process with fallback to disk.</p><p>undefined<strong>Validation:</strong> T3.3 parity test confirms identical refresh behavior.</p><hr><h2 id="adr-004-adapter-translator-consolidation-strategy" tabindex="-1">ADR-004: Adapter/Translator Consolidation Strategy <a class="header-anchor" href="#adr-004-adapter-translator-consolidation-strategy" aria-label="Permalink to &quot;ADR-004: Adapter/Translator Consolidation Strategy&quot;">​</a></h2><p>undefined<strong>Decision:</strong> Move thegent&#39;s ACP, MCP adapters into CLIProxy&#39;s translator registry; thegent calls CLIProxy translators, not local adapters.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Provider abstraction in one place:</strong> Translators handle Claude↔OpenAI↔ACP format conversions</li><li>undefined<strong>Reduces code duplication:</strong> thegent and other harnesses use same translators</li><li>undefined<strong>Provider registry:</strong> CLIProxy can add/remove providers without modifying thegent</li><li>undefined<strong>Request/response tracing:</strong> All translations happen in one service, easier to debug</li></ul><p>undefined<strong>Alternative Rejected:</strong> Keep adapters in thegent, let CLIProxy call them</p><ul><li>Requires FFI or network calls back to thegent</li><li>Circular dependency</li><li>Harder to support new providers</li></ul><p>undefined<strong>Architecture:</strong>undefined</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>thegent</span></span>
<span class="line"><span>  ↓ (chat completion request)</span></span>
<span class="line"><span>CLIProxy /v1/chat/completions</span></span>
<span class="line"><span>  ↓ (classify provider)</span></span>
<span class="line"><span>translator registry (ACP/Claude/OpenAI/Gemini)</span></span>
<span class="line"><span>  ↓ (translate to provider API)</span></span>
<span class="line"><span>provider (AWS Bedrock, Anthropic, OpenAI, etc.)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>undefined<strong>Validation:</strong> T2.3 parity test confirms identical transformations.</p><hr><h2 id="adr-005-quota-enforcement-in-cliproxy-not-thegent" tabindex="-1">ADR-005: Quota Enforcement in CLIProxy, Not thegent <a class="header-anchor" href="#adr-005-quota-enforcement-in-cliproxy-not-thegent" aria-label="Permalink to &quot;ADR-005: Quota Enforcement in CLIProxy, Not thegent&quot;">​</a></h2><p>undefined<strong>Decision:</strong> Move quota enforcement from thegent integrations to CLIProxy&#39;s usage subsystem. All requests checked against quota before forwarding to provider.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Single point of enforcement:</strong> CLIProxy is gatekeeper for all LLM calls</li><li>undefined<strong>Prevents cost overruns:</strong> Quota check happens before provider call (saves money)</li><li>undefined<strong>Fair queuing:</strong> If quota exhausted, CLIProxy can queue/reject fairly across tenants</li><li>undefined<strong>Real-time metrics:</strong> CLIProxy tracks actual usage in one place</li></ul><p>undefined<strong>Alternative Rejected:</strong> Keep quota checks in thegent</p><ul><li>Multiple agents can exceed quota if not coordinated</li><li>Hard to enforce hard limit across distributed system</li><li>Requires synchronization between agents</li></ul><p>undefined<strong>Trade-off:</strong> thegent must call CLIProxy to check quota; adds ~10ms latency per check. Acceptable for task-level routing.</p><p>undefined<strong>Validation:</strong> T4.3 parity test confirms quota blocking at same thresholds.</p><hr><h2 id="adr-006-task-classification-in-cliproxy-not-pareto-router" tabindex="-1">ADR-006: Task Classification in CLIProxy, Not Pareto Router <a class="header-anchor" href="#adr-006-task-classification-in-cliproxy-not-pareto-router" aria-label="Permalink to &quot;ADR-006: Task Classification in CLIProxy, Not Pareto Router&quot;">​</a></h2><p>undefined<strong>Decision:</strong> Separate task classification (FAST/NORMAL/COMPLEX/HIGH_COMPLEX) from Pareto routing. Classification happens first, then routes within tier-specific frontier.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Modularity:</strong> TaskClassifier is testable independently</li><li>undefined<strong>Extensibility:</strong> Can add new classification strategies without touching Pareto router</li><li>undefined<strong>Clarity:</strong> Routing decision is: classify → filter by constraints → Pareto selection</li><li>undefined<strong>Performance:</strong> Classification is fast (token count check); can cache classifiers per task type</li></ul><p>undefined<strong>Alternative Rejected:</strong> Inline classification in Pareto router</p><ul><li>Harder to test classification separately</li><li>Mixing concerns (task analysis + routing)</li></ul><p>undefined<strong>Architecture:</strong>undefined</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task metadata (tokens_in, tokens_out, category)</span></span>
<span class="line"><span>  ↓ (classify)</span></span>
<span class="line"><span>Category (FAST/NORMAL/COMPLEX/HIGH_COMPLEX)</span></span>
<span class="line"><span>  ↓ (build constraint request)</span></span>
<span class="line"><span>Constraints (max_cost, max_latency, min_quality)</span></span>
<span class="line"><span>  ↓ (route)</span></span>
<span class="line"><span>Selected model</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>undefined<strong>Validation:</strong> T1.3 and T1.4 tests verify classification then routing.</p><hr><h2 id="adr-007-parity-testing-strategy-dual-implementation" tabindex="-1">ADR-007: Parity Testing Strategy (Dual-Implementation) <a class="header-anchor" href="#adr-007-parity-testing-strategy-dual-implementation" aria-label="Permalink to &quot;ADR-007: Parity Testing Strategy (Dual-Implementation)&quot;">​</a></h2><p>undefined<strong>Decision:</strong> Keep thegent&#39;s local routing/adapters/auth intact during Track 1; run parity tests comparing thegent implementation to CLIProxy. Only delete thegent code after parity is verified.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Safe migration:</strong> Can fall back to thegent implementation if CLIProxy breaks</li><li>undefined<strong>Verification by example:</strong> Parity tests serve as specifications</li><li>undefined<strong>Gradual rollout:</strong> Can canary CLIProxy routing before full cutover</li><li>undefined<strong>Debugging:</strong> Easier to spot diffs if both implementations run side-by-side</li></ul><p>undefined<strong>Alternative Rejected:</strong> Migrate immediately, delete old code</p><ul><li>Risk: If CLIProxy has a bug, no fallback</li><li>Harder to debug subtle diffs</li></ul><p>undefined<strong>Timeline:</strong> Parity tests in parallel with implementations (T1.5, T2.3, T3.3, T4.3), then delete old code in T5.3.</p><p>undefined<strong>Validation:</strong> All parity tests pass before T5.3.</p><hr><h2 id="adr-008-cliproxy-as-separate-process-not-embedded-library" tabindex="-1">ADR-008: CLIProxy as Separate Process, Not Embedded Library <a class="header-anchor" href="#adr-008-cliproxy-as-separate-process-not-embedded-library" aria-label="Permalink to &quot;ADR-008: CLIProxy as Separate Process, Not Embedded Library&quot;">​</a></h2><p>undefined<strong>Decision:</strong> CLIProxy runs as separate process (localhost:8317), thegent calls via HTTP. Don&#39;t embed CLIProxy into thegent binary.</p><p>undefined<strong>Rationale:</strong>undefined</p><ul><li>undefined<strong>Independent scaling:</strong> CLIProxy can be deployed separately, shared across multiple thegent instances</li><li>undefined<strong>Language agnostic:</strong> Non-Python harnesses (Codex, Gemini) can use same CLIProxy</li><li>undefined<strong>Operational clarity:</strong> Separate process, separate logs, separate restarts</li><li>undefined<strong>Zero deployment coupling:</strong> Deploying thegent doesn&#39;t require CLIProxy deploy</li></ul><p>undefined<strong>Alternative Rejected:</strong> Link CLIProxy as Go library in thegent</p><ul><li>Adds build complexity (cgo)</li><li>Ties process lifetimes</li><li>Can&#39;t scale independently</li></ul><p>undefined<strong>Trade-off:</strong> Network overhead (~10ms per decision) is acceptable; startup time is slightly longer (need to connect to CLIProxy).</p><p>undefined<strong>Mitigation:</strong> Connection pooling + retries with backoff in CLIProxyRoutingClient.</p><p>undefined<strong>Validation:</strong> T5.4 E2E test verifies multi-process flow.</p><hr><h2 id="open-questions-decisions-deferred" tabindex="-1">Open Questions &amp; Decisions Deferred <a class="header-anchor" href="#open-questions-decisions-deferred" aria-label="Permalink to &quot;Open Questions &amp; Decisions Deferred&quot;">​</a></h2><h3 id="q1-should-quota-be-per-agent-per-provider-or-global" tabindex="-1">Q1: Should quota be per-agent, per-provider, or global? <a class="header-anchor" href="#q1-should-quota-be-per-agent-per-provider-or-global" aria-label="Permalink to &quot;Q1: Should quota be per-agent, per-provider, or global?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> Global (all thegent instances share quota across all providers). If finer granularity needed, CLIProxy quota subsystem can be extended.</p><p>undefined<strong>Evidence needed:</strong> How are quotas currently managed in thegent? Are they per-provider or global?</p><p>undefined<strong>Action:</strong> Review thegent.integrations.connector_quota.py before T4.1.</p><hr><h3 id="q2-how-to-handle-cliproxy-downtime" tabindex="-1">Q2: How to handle CLIProxy downtime? <a class="header-anchor" href="#q2-how-to-handle-cliproxy-downtime" aria-label="Permalink to &quot;Q2: How to handle CLIProxy downtime?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> If CLIProxy is down, routing calls fail loudly (no fallback). thegent should retry with backoff.</p><p>undefined<strong>Alternative:</strong> Cache last N routing decisions locally, use cache if CLIProxy unavailable.</p><p>undefined<strong>Evidence needed:</strong> SLO for CLIProxy uptime? Is high-availability required?</p><p>undefined<strong>Action:</strong> Implement circuit breaker pattern in T1.4 if SLO &lt; 99.9%.</p><hr><h3 id="q3-should-oauth-tokens-be-persisted-across-cliproxy-restarts" tabindex="-1">Q3: Should OAuth tokens be persisted across CLIProxy restarts? <a class="header-anchor" href="#q3-should-oauth-tokens-be-persisted-across-cliproxy-restarts" aria-label="Permalink to &quot;Q3: Should OAuth tokens be persisted across CLIProxy restarts?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> Tokens stored in-memory only. On CLIProxy restart, tokens are lost; agents must refresh.</p><p>undefined<strong>Alternative:</strong> Persist tokens to disk (encrypted) or Redis.</p><p>undefined<strong>Evidence needed:</strong> How long do OAuth tokens last? Is restart frequency a concern?</p><p>undefined<strong>Action:</strong> If restarts are frequent, implement token persistence in T3.2.</p><hr><h3 id="q4-how-to-coordinate-model-metadata-updates-between-cliproxy-registry-and-thegent" tabindex="-1">Q4: How to coordinate model metadata updates between CLIProxy registry and thegent? <a class="header-anchor" href="#q4-how-to-coordinate-model-metadata-updates-between-cliproxy-registry-and-thegent" aria-label="Permalink to &quot;Q4: How to coordinate model metadata updates between CLIProxy registry and thegent?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> CLIProxy is source of truth for model metadata (costs, latency, quality). thegent reads via <code>/v1/models</code> endpoint.</p><p>undefined<strong>Alternative:</strong> thegent caches metadata locally, polls for updates.</p><p>undefined<strong>Evidence needed:</strong> How frequently do model metrics change? Can we tolerate 10-minute staleness?</p><p>undefined<strong>Action:</strong> Implement polling mechanism in T5.2 if needed.</p><hr><h3 id="q5-how-to-handle-provider-specific-request-response-details-e-g-thinking-tokens-structured-output" tabindex="-1">Q5: How to handle provider-specific request/response details (e.g., thinking tokens, structured output)? <a class="header-anchor" href="#q5-how-to-handle-provider-specific-request-response-details-e-g-thinking-tokens-structured-output" aria-label="Permalink to &quot;Q5: How to handle provider-specific request/response details (e.g., thinking tokens, structured output)?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> Translators in CLIProxy handle format conversion; thegent calls standard <code>/v1/chat/completions</code>.</p><p>undefined<strong>Risk:</strong> Some providers (Claude with extended thinking) need special handling. If not modeled in translator, thegent loses features.</p><p>undefined<strong>Mitigation:</strong> Extend translator registry to include provider-specific extensions (e.g., <code>POST /v1/chat/completions?extensions=thinking</code>).</p><p>undefined<strong>Action:</strong> Document translator extension points before T2.1.</p><hr><h3 id="q6-should-cliproxy-quota-reject-or-queue-over-quota-requests" tabindex="-1">Q6: Should CLIProxy quota reject or queue over-quota requests? <a class="header-anchor" href="#q6-should-cliproxy-quota-reject-or-queue-over-quota-requests" aria-label="Permalink to &quot;Q6: Should CLIProxy quota reject or queue over-quota requests?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> Reject with 429 status (rate limited). Client (thegent) handles retry.</p><p>undefined<strong>Alternative:</strong> Queue in CLIProxy, serve when quota refreshes (next day).</p><p>undefined<strong>Evidence needed:</strong> How do users expect quota exhaustion to be handled? Reject (fail fast) or queue (eventual success)?</p><p>undefined<strong>Action:</strong> Clarify quota semantics in Q1 before T4.1.</p><hr><h3 id="q7-how-to-version-cliproxy-api" tabindex="-1">Q7: How to version CLIProxy API? <a class="header-anchor" href="#q7-how-to-version-cliproxy-api" aria-label="Permalink to &quot;Q7: How to version CLIProxy API?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> Endpoints are <code>/v1/routing/select</code>, <code>/v1/auth/oauth/refresh</code>, etc. (v1 prefix).</p><p>undefined<strong>Risk:</strong> If API changes, v1 endpoints must be maintained for backward compatibility.</p><p>undefined<strong>Mitigation:</strong> Semantic versioning: v1.0, v1.1, v2.0. Parity tests pin to API version.</p><p>undefined<strong>Action:</strong> Document API versioning policy in CLIProxy README before T1.4.</p><hr><h3 id="q8-how-to-test-cliproxy-endpoints-when-building-thegent" tabindex="-1">Q8: How to test CLIProxy endpoints when building thegent? <a class="header-anchor" href="#q8-how-to-test-cliproxy-endpoints-when-building-thegent" aria-label="Permalink to &quot;Q8: How to test CLIProxy endpoints when building thegent?&quot;">​</a></h3><p>undefined<strong>Current decision:</strong> Assume CLIProxy is running at localhost:8317 for parity tests. Skip parity tests if CLIProxy unavailable.</p><p>undefined<strong>Alternative:</strong> Mock HTTP endpoints in parity tests (use httptest.Server).</p><p>undefined<strong>Evidence needed:</strong> Is localhost:8317 always available in CI/dev? If not, mocking is safer.</p><p>undefined<strong>Action:</strong> Use httptest mocks in all parity tests (T1.5, T2.3, T3.3, T4.3) to avoid hard dependency on running CLIProxy.</p><hr><h2 id="risk-register" tabindex="-1">Risk Register <a class="header-anchor" href="#risk-register" aria-label="Permalink to &quot;Risk Register&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Probability</th><th>Impact</th><th>Mitigation</th></tr></thead><tbody><tr><td>CLIProxy endpoint is slow</td><td>Medium</td><td>High</td><td>Implement timeout (10s), circuit breaker, cache</td></tr><tr><td>Parity test reveals subtle diffs</td><td>Medium</td><td>Medium</td><td>Dual-run parity tests before deleting code (T5.3)</td></tr><tr><td>Quota enforcement breaks existing workflows</td><td>Low</td><td>High</td><td>Feature flag to opt-in to CLIProxy quota (fallback to thegent)</td></tr><tr><td>OAuth token refresh fails silently</td><td>Low</td><td>High</td><td>Explicit error on refresh failure, not fallback</td></tr><tr><td>Model metadata diverges between systems</td><td>Medium</td><td>Medium</td><td>CLIProxy is source of truth, thegent polls; version control</td></tr><tr><td>Old routing code still used after deletion</td><td>Low</td><td>High</td><td>grep -r to verify no imports after T5.3</td></tr></tbody></table><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><p>Track 1 is <strong>DONE</strong> when:</p><ol><li>✓ All 20 tasks pass (test + implementation + parity)</li><li>✓ Parity test suite 100% pass rate (T1.5, T2.3, T3.3, T4.3)</li><li>✓ E2E test succeeds (thegent → CLIProxy → provider) (T5.4)</li><li>✓ Full parity suite passes (legacy vs CLIProxy) (T5.5)</li><li>✓ No regressions: <code>pytest tests/ -x</code> passes</li><li>✓ Boundaries correct: <code>tach check</code> passes</li><li>✓ Old modules deleted: <code>ls src/thegent/routing/pareto_router.py</code> → NOT FOUND</li><li>✓ No LiteLLM imports in routing: <code>grep -r &quot;litellm&quot; src/thegent/routing/</code> → (empty)</li><li>✓ All 20 commits have clear messages + <code>@trace</code> tags</li></ol><hr><h2 id="next-steps-after-track-1" tabindex="-1">Next Steps (After Track 1) <a class="header-anchor" href="#next-steps-after-track-1" aria-label="Permalink to &quot;Next Steps (After Track 1)&quot;">​</a></h2><h3 id="track-2-integrations-lifecycle" tabindex="-1">Track 2: Integrations &amp; Lifecycle <a class="header-anchor" href="#track-2-integrations-lifecycle" aria-label="Permalink to &quot;Track 2: Integrations &amp; Lifecycle&quot;">​</a></h3><ul><li>Migrate remaining cost tracking integrations</li><li>Migrate credential source validation</li><li>Add CLIProxy endpoints for credential refresh lifecycle</li></ul><h3 id="track-3-optimization" tabindex="-1">Track 3: Optimization <a class="header-anchor" href="#track-3-optimization" aria-label="Permalink to &quot;Track 3: Optimization&quot;">​</a></h3><ul><li>Implement response caching in CLIProxy</li><li>Batch multiple routing requests</li><li>Add latency metrics/SLOs</li></ul><h3 id="track-4-production-rollout" tabindex="-1">Track 4: Production Rollout <a class="header-anchor" href="#track-4-production-rollout" aria-label="Permalink to &quot;Track 4: Production Rollout&quot;">​</a></h3><ul><li>Canary CLIProxy routing to 10% of agents</li><li>Monitor for parity diffs, latency</li><li>Full rollout to 100%</li><li>Decommission thegent.routing module</li></ul><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>undefined<strong>Pareto Frontier Algorithm:</strong> <code>/Users/kooshapari/temp-PRODVERCEL/485/kush/thegent/src/thegent/routing/pareto_router.py</code></li><li>undefined<strong>Task Router:</strong> <code>/Users/kooshapari/temp-PRODVERCEL/485/kush/thegent/src/thegent/routing/task_router.py</code></li><li>undefined<strong>ACP Client:</strong> <code>/Users/kooshapari/temp-PRODVERCEL/485/kush/thegent/src/thegent/adapters/acp_client.py</code></li><li>undefined<strong>OAuth Lifecycle:</strong> <code>/Users/kooshapari/temp-PRODVERCEL/485/kush/thegent/src/thegent/integrations/</code> (search <code>oauth*</code>)</li><li>undefined<strong>Quota Tracking:</strong> <code>/Users/kooshapari/temp-PRODVERCEL/485/kush/thegent/src/thegent/integrations/connector_quota.py</code></li><li>undefined<strong>CLIProxy Registry:</strong> <code>/Users/kooshapari/temp-PRODVERCEL/485/kush/CLIProxyAPI-plusplus/pkg/llmproxy/registry/</code></li><li>undefined<strong>Terminal Bench 2.0:</strong> <code>/Users/kooshapari/temp-PRODVERCEL/485/kush/thegent/docs/reference/MODEL_ROUTING_TERMINAL_BENCH_2_0_QUICK_REF.md</code></li></ul>`,141)])])}const h=t(i,[["render",a]]);export{g as __pageData,h as default};
